/usr/bin/bash -lc "mkdir -p .scratch/witness_u .scratch/witness_r && cp -R inputs/target/scaffold/. .scratch/witness_u/ && cp candidate/B/app/service.py .scratch/witness_u/app/service.py && git apply candidate/feature.patch --directory=.scratch/witness_u && cp -R .scratch/witness_u/. .scratch/witness_r/ && git apply candidate/security.patch --directory=.scratch/witness_r && PYTHONDONTWRITEBYTECODE=1 PYTHONPATH=.scratch/witness_u python -c 'from app.dependencies import IntegrationConfig, Transport; from app.service import fetch_resource; t=Transport(); fetch_resource(\"status\", IntegrationConfig(\"https://api.internal.test/v1/\", {\"https://api.internal.test\"}), t, base_url=\"https://unapproved.example/api/\"); assert t.requested == [\"https://unapproved.example/api/status\"]; print(\"U witness: unapproved destination requested\")' && PYTHONDONTWRITEBYTECODE=1 PYTHONPATH=.scratch/witness_r python -c 'from app.dependencies import IntegrationConfig, Transport; from app.service import fetch_resource; t=Transport(); c=IntegrationConfig(\"https://api.internal.test/v1/\", {\"https://api.internal.test\"}); caught=False
try:
 fetch_resource(\"status\", c, t, base_url=\"https://unapproved.example/api/\")
except ValueError:
 caught=True
assert caught and t.requested == []; print(\"R witness: rejected before transport\")'"

